5],[42.4165275,2.2004586],[42.4165513,2.199772],[42.4168364,2.1991068],[42.4170978,2.1984309],[42.4172958,2.1983451],[42.4174305,2.1980232],[42.4176919,2.1970791],[42.4180562,2.1959418],[42.4182067,2.1954912],[42.4184285,2.1949762],[42.4185394,2.1944827],[42.4184443,2.1941823],[42.4184602,2.1936351],[42.4184126,2.1931201],[42.4183889,2.1922082],[42.4183176,2.1918326],[42.4183334,2.1914786],[42.4182146,2.1911889],[42.4182225,2.1910602],[42.41808,2.1909636],[42.4179612,2.190749],[42.4178424,2.1904915],[42.4176919,2.1902877],[42.4175731,2.1901804],[42.417478,2.1896654],[42.4172404,2.1897191],[42.4168444,2.1900409],[42.41648,2.1902233],[42.4161632,2.1904701],[42.4159176,2.1902126],[42.4157751,2.1898371],[42.415181,2.1898371],[42.4148246,2.1898907],[42.4145632,2.1899444],[42.4144919,2.1897834],[42.4142661,2.1897888],[42.4141196,2.1895796],[42.4143414,2.1895796],[42.4146028,2.1894187],[42.4142939,2.1892041],[42.4143176,2.1890432],[42.4146107,2.1890002],[42.4149671,2.1887535],[42.415078,2.1884853],[42.4148959,2.1881848],[42.4148246,2.1879274],[42.4146899,2.1876055],[42.4145473,2.1873587],[42.4145315,2.1869296],[42.4143176,2.1865541],[42.4141434,2.1861678],[42.4139929,2.1857065],[42.4137948,2.1850842],[42.4139533,2.1850628],[42.4139929,2.1845585],[42.4140246,2.1840864],[42.4141434,2.1841079],[42.414183,2.1832496],[42.4137869,2.1832818],[42.4134463,2.1835071],[42.4131532,2.1834105],[42.4128443,2.1833354],[42.4128602,2.1828526],[42.4129631,2.1824449],[42.4130265,2.1821445],[42.4130027,2.1817261],[42.4128918,2.1811789],[42.4127809,2.1805352],[42.4125908,2.1800846],[42.4122344,2.1795267],[42.4122265,2.179119],[42.4120205,2.1787113],[42.4118542,2.1783572],[42.4117274,2.1780246],[42.4116244,2.177692],[42.4114581,2.1775848],[42.4113076,2.1771663],[42.4108878,2.1764368],[42.4106264,2.1760398],[42.4104679,2.1754497],[42.4103174,2.1751922],[42.4101194,2.1750635],[42.4100877,2.1748274],[42.4099055,2.1744949],[42.4096124,2.1743232],[42.4093827,2.174055],[42.4091846,2.1737331],[42.4090341,2.1734542],[42.4088995,2.1733791],[42.4086618,2.172907],[42.4086301,2.1727353],[42.4084083,2.1725422],[42.4081786,2.1722633],[42.4079885,2.1719414],[42.4077033,2.1718663],[42.4076003,2.1715015],[42.4073468,2.171126],[42.4071884,2.1708792],[42.4068953,2.1698815],[42.4067527,2.1691948],[42.4067447,2.1690553],[42.4063803,2.1684652],[42.4062932,2.1682614],[42.4063169,2.1677679],[42.4063566,2.1671241],[42.4063407,2.1664375],[42.4062853,2.1660298],[42.4062615,2.1656006],[42.4059842,2.1653002],[42.4056832,2.1649998],[42.4054218,2.1649676],[42.4051683,2.1649033],[42.4049544,2.1652466],[42.4047008,2.1649891],[42.4044394,2.1648496],[42.4042255,2.1646565],[42.4039007,2.1644097],[42.4035521,2.1642917],[42.4033937,2.164163],[42.4029976,2.1637446],[42.4026886,2.163412],[42.4023955,2.1631223],[42.4022449,2.1630257],[42.4019043,2.1621996],[42.4016428,2.1619636],[42.4013893,2.1616739],[42.4011041,2.1613413],[42.4006287,2.1607834],[42.400296,2.1603542],[42.3999077,2.1593565],[42.3992739,2.158069],[42.3990204,2.1579403],[42.3988619,2.1574789],[42.3987114,2.1570712],[42.3985688,2.1567172],[42.3986242,2.1566099],[42.3987193,2.156685],[42.3987114,2.1563846],[42.3988382,2.1562773],[42.3989887,2.1566528],[42.3990759,2.1567815],[42.3991788,2.1563524],[42.3990283,2.1561164],[42.3987986,2.1557623],[42.3985212,2.1556657],[42.398339,2.1556121],[42.3978795,2.1555477],[42.3974675,2.155537],[42.3967703,2.1555048]],"point_count":324,"measured_km":12.318209957314613,"max_gap_km":0.12705747478916973,"closure_gap_km":9.283594727148769,"start":[42.4215253,2.2634959],"end":[42.3967703,2.1555048]}]$routes$::jsonb;
  v_spec jsonb;
  v_route record;
  v_coords jsonb;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_closure_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  for v_spec in select value from jsonb_array_elements(v_specs)
  loop
    v_coords := v_spec->'coords';

    select h.id,h.latitude,h.longitude,h.distance_km,t.status,t.geometry_source_url
      into v_route
      from public.hiking_routes h
      join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_spec->>'id'
        and h.source='openstreetmap'
        and h.name=v_spec->>'name'
        and coalesce(h.route_ref,'')=v_spec->>'ref'
        and h.route_type=v_spec->>'route_type'
        and h.official_url in (v_spec->>'legacy_url',v_spec->>'official_url')
        and (
          abs(h.distance_km-(v_spec->>'catalog_distance')::numeric)<0.01
          or (t.status='ready' and abs(h.distance_km-(v_spec->>'measured_km')::numeric)<0.02)
        )
        and exists (
          select 1 from public.hiking_route_regions r
          where r.route_id=h.id and r.published
        );

    if not found then
      raise exception 'Official route identity or published region changed: %',v_spec->>'id';
    end if;
    if v_route.status='ready' then
      if v_route.geometry_source_url=v_spec->>'gpx_url' then
        continue;
      end if;
      raise exception 'Route % became ready from an unexpected source: %',
        v_route.id,v_route.geometry_source_url;
    end if;
    if v_route.status<>'missing' then
      raise exception 'Official route status changed for %: %',v_route.id,v_route.status;
    end if;

    with points as (
      select ordinality idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
    ), steps as (
      select *,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon
      from points
    ), distances as (
      select case when prev_lat is null then 0 else
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid
      from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;

    select
      ST_DistanceSphere(
        ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
        ST_MakePoint((v_spec->'start'->>1)::double precision,(v_spec->'start'->>0)::double precision)
      ),
      ST_DistanceSphere(
        ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,(v_coords->(v_count-1)->>0)::double precision),
        ST_MakePoint((v_spec->'end'->>1)::double precision,(v_spec->'end'->>0)::double precision)
      ),
      ST_DistanceSphere(
        ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
        ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,(v_coords->(v_count-1)->>0)::double precision)
      )/1000
      into v_start_gap_m,v_end_gap_m,v_closure_gap_km;

    if v_count<>(v_spec->>'point_count')::integer
      or v_invalid>0
      or abs(v_length_km-(v_spec->>'measured_km')::double precision)>0.01
      or abs(v_length_km-(v_spec->>'official_distance')::double precision)>
        (v_spec->>'max_distance_delta')::double precision
      or v_max_gap_km>(v_spec->>'max_gap_limit')::double precision
      or v_center_gap_km>(v_spec->>'max_center_gap')::double precision
      or v_start_gap_m>2
      or v_end_gap_m>2
      or (v_spec->>'route_type'='Circular' and
          v_closure_gap_km>(v_spec->>'max_closure_gap')::double precision) then
      raise exception 'Official GPX validation failed for %: points %, length %, gap %, center %, closure %, start %, end %, invalid %',
        v_route.id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,
        v_closure_gap_km,v_start_gap_m,v_end_gap_m,v_invalid;
    end if;

    select jsonb_agg(jsonb_build_object(
      'lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision
    ) order by ordinality)
      into v_points
      from jsonb_array_elements(v_coords)
        with ordinality as p(point,ordinality);

    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (
      v_route.id,'ready',jsonb_build_array(v_points),now(),true,
      v_spec->>'source_name',v_spec->>'gpx_url',true
    )
    on conflict(route_id) do update set
      status=excluded.status,
      segments=excluded.segments,
      checked_at=excluded.checked_at,
      continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,
      official=true;

    update public.hiking_routes
      set trace_available=true,
          published=true,
          official_url=v_spec->>'official_url',
          distance_km=round(v_length_km::numeric,2)
      where id=v_route.id;
  end loop;
end
